static List<List<Integer>> buildGraph(int n, int[][] edges) {
  List<List<Integer>> adj = new ArrayList<>();
  for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
  for (int[] e : edges) {
    adj.get(e[0]).add(e[1]);
    adj.get(e[1]).add(e[0]);
  }
  return adj;
}

static int numIslands(char[][] grid) {
  int count = 0;
  for (int r = 0; r < grid.length; r++)
    for (int c = 0; c < grid[0].length; c++)
      if (grid[r][c] == '1') { count++; sink(grid, r, c); }
  return count;
}
static void sink(char[][] g, int r, int c) {
  if (r < 0 || c < 0 || r >= g.length || c >= g[0].length || g[r][c] != '1') return;
  g[r][c] = '0';
  sink(g, r + 1, c); sink(g, r - 1, c); sink(g, r, c + 1); sink(g, r, c - 1);
}

static boolean canFinish(int n, int[][] prerequisites) {
  List<List<Integer>> adj = new ArrayList<>();
  for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
  int[] indeg = new int[n];
  for (int[] p : prerequisites) { adj.get(p[1]).add(p[0]); indeg[p[0]]++; }
  Deque<Integer> q = new ArrayDeque<>();
  for (int i = 0; i < n; i++) if (indeg[i] == 0) q.offer(i);
  int done = 0;
  while (!q.isEmpty()) {
    int u = q.poll();
    done++;
    for (int v : adj.get(u)) if (--indeg[v] == 0) q.offer(v);
  }
  return done == n;
}

static Node cloneGraph(Node node) {
  if (node == null) return null;
  return copy(node, new HashMap<>());
}
static Node copy(Node n, Map<Node, Node> seen) {
  if (seen.containsKey(n)) return seen.get(n);
  Node c = new Node(n.val);
  seen.put(n, c);
  for (Node nb : n.neighbors) c.neighbors.add(copy(nb, seen));
  return c;
}
